mapper.insert:
INSERT INTO user_auth_session (
    session_id, user_id, refresh_token_hash, device_name, ip, user_agent,
    expires_at, last_seen_at, revoked_at, created_at
) VALUES (
    #{sessionId}, #{userId}, #{refreshTokenHash}, #{deviceName}, #{ip}, #{userAgent},
    #{expiresAt}, #{lastSeenAt}, #{revokedAt}, #{createdAt}
)

mapper.update:
UPDATE user_auth_session
SET refresh_token_hash = #{nextRefreshTokenHash},
    last_seen_at = #{lastSeenAt},
    expires_at = LEAST(#{expiresAt}, DATE_ADD(created_at, INTERVAL 365 DAY))
WHERE session_id = #{sessionId}
  AND refresh_token_hash = #{currentRefreshTokenHash}
  AND revoked_at IS NULL
  AND expires_at > #{lastSeenAt}
  AND DATE_ADD(created_at, INTERVAL 365 DAY) > #{lastSeenAt}

UPDATE user_auth_session
SET revoked_at = #{revokedAt}
WHERE refresh_token_hash = #{refreshTokenHash}
  AND revoked_at IS NULL

UPDATE user_auth_session
SET revoked_at = #{revokedAt}
WHERE user_id = #{userId}
  AND revoked_at IS NULL

UPDATE user_auth_session
SET revoked_at = #{revokedAt}
WHERE user_id = #{userId}
  AND revoked_at IS NULL
  AND session_id <> #{retainedSessionId}
